<!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Preview do certificado</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.8/dist/css/bootstrap.min.css" rel="stylesheet"><style>body{background:#eef1f5}.certificate-image{display:block;max-width:100%;height:auto;margin:auto;box-shadow:0 8px 30px #0002}@media print{.page-info{display:none}body,main{background:#fff!important;padding:0!important}.certificate-image{width:100%;box-shadow:none}}</style></head><body><header class="page-info bg-white border-bottom"><div class="container-fluid py-3"><div class="d-flex flex-wrap justify-content-between align-items-center gap-3"><div><h1 class="h4 mb-2">Preview do certificado</h1><div><strong>Participante:</strong> {{ $participant }}</div><div><strong>Evento:</strong> {{ $event }}</div><div><strong>Atividade:</strong> {{ $activity }}</div><div><strong>Horas:</strong> {{ $hours }}</div></div><button type="button" class="btn btn-primary" onclick="window.print()">Visualizar impressão</button></div></div></header><main class="p-4"><img class="certificate-image" src="{{ $image }}" alt="Preview do certificado"></main></body></html>
